INSERT INTO `catalog_pages` VALUES (299, 376, '2014_health_spa', '2014 - Spa Santé', 'default_3x3', 1, 62, 1, 11, '1', '1', '0', '0', 'catalog_header_spa', 'catalog_teaser_spa', '', 'Sometimes, all you want is a nice relaxing spa day. With this furni line, you can enjoy one with your Valentine!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (25, -1, '', 'Insignes', 'default_3x3', 1, 875, 1, 5, '1', '1', '0', '0', 'catalog_header_badgedisplay', 'badgedisplay_promo2', '', 'You worked hard to get your badges, right? Now\'s the time to show it off, grab a display case and choose your favorite badge to show off!', '', '', '', 0, '');
