INSERT INTO `catalog_pages` VALUES (28, 209, 'alhambra', 'Alhambra', 'default_3x3', 1, 12, 1, 1, '1', '1', '0', '0', 'alhambra_header', 'alhambra_teaser', '', 'For the cold Arabian nights and hot Arabian days, you\'ll need a palace.. And we have just what you need! Green blossom print should cover it just fine!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (302, 209, 'asian', 'asiatique', 'default_3x3', 1, 15, 1, 1, '1', '1', '0', '0', 'catalog_asian_headline1', 'catalog_asian_teaser1', '', 'Ting tong! Ching chong? Ting chong ting, ping ping! I mean uh.. with our authentic Chinese furniture, you can make a beautiful oriental room!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (303, 209, 'bensalem', 'Bensalem', 'default_3x3', 1, 18, 1, 2, '1', '1', '0', '0', 'catalog_lc_headline2_en', 'catalog_lc_teaser1_en_001', '', 'Glub... glub... glub...', '', '', '', 0, '');
