INSERT INTO `catalog_pages` VALUES (31, 209, 'japan', 'Japon', 'default_3x3', 1, 36, 1, 10, '1', '1', '0', '0', 'catalog_jap_headline1', 'catalog_jap_teaser3_en', '', 'We have sushi, tatami and katana\'s! I have no idea what the difference is, but I sure know its Japanese! Fulfil your fantasies and buy some today!', '', '', '', 0, '');
