INSERT INTO `catalog_pages` VALUES (467, 209, 'school', 'École', 'default_3x3', 1, 130, 1, 20, '1', '1', '0', '0', 'ruletheschool_header', 'catalog_school_teaser', '', 'Sick of being told what to do? Want to be the boss of someone else for a change? Well now you can with our very own school range!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (93, 90, 'bunny_manic', 'Lapin - Maniaque', 'pets', 1, 149, 1, 99, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'One of the most feared creatures in nature, and perhaps the most misunderstood. The majority of Spiders have sharp fangs that inject venom into their prey- but don\'t worry, these spiders won\'t bite ! Maybe...', '', 'Name your pet:', '', 0, '');
INSERT INTO `catalog_pages` VALUES (92, 90, 'bunny_bored', 'Lapin - Ennuyé', 'pets', 1, 150, 1, 99, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'These mischievous little pets have travelled all the way from the deep jungles of WobbahLand! Adorable as they are naughty, these little guys love a good sing-a-long.', '', 'Name your Obbah Wobbah:', 'Select a colour:', 0, '');
INSERT INTO `catalog_pages` VALUES (91, 90, 'bunny_bad', 'Lapin - Mauvais', 'pets', 1, 151, 1, 99, '1', '1', '0', '0', 'catalog_horse_header2_en', '', '', 'You can ride your horse around the Hotel and also customize its body and hair colour.', '', 'Name Your Horse:', '', 0, '');
INSERT INTO `catalog_pages` VALUES (232, 69694306, 'pterodactyl', 'Ptérodactyles', 'pets', 1, 260, 7, 11, '0', '0', '0', '0', 'jurassic15_catalog_header', 'dino_pets', '', 'These pterrific pets have a fierce appearance with long talons and sharp teeth, but their sweet nature always shines through! Ultra laid-back, these \'flying lizards\' love nothing more than spending time with their owner, soaring through the Hotel skies and eating their favourite food...the humble kale leaf.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (523, 1274, 'football', 'Football', 'default_3x3', 1, 56, 1, 6, '1', '1', '0', '0', 'catalog_football_001', 'flags', '', 'Whether you call it soccer, football or futbol... you can enjoy the game right here in Habbo! Get a ball and kick it, bounce it, pass it, control it and steal it!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (54, 209, 'prison', 'Prison', 'default_3x3', 1, 240, 1, 17, '1', '1', '0', '0', 'prisonheader', 'prisonteaser', '', 'Hey, he\'s escaping! Just kidding, no one\'s getting out of these high security cells!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (55, 209, 'tv_studio', 'Studio de télévision', 'default_3x3', 1, 136, 1, 21, '1', '1', '0', '0', 'header_studio', 'teaser_studio', '', 'The Studio range lets YOU be your own music prncer!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (69694306, 277, 'broken_pets1', 'Cassé', 'default_3x3', 1, 6532, 7, 0, '0', '0', '0', '0', '', '', '', NULL, NULL, NULL, NULL, 0, '');
INSERT INTO `catalog_pages` VALUES (102, 69694306, 'velociraptor', 'Vélociraptors', 'pets', 1, 32652, 7, 16, '0', '0', '0', '0', 'jurassic15_catalog_header', 'dino_pets', '', 'Swift and sneaky, these reptiles have a reputation for being somewhat high-maintenance, incredibly intellectual and endlessly troublesome! You\'ll often find them pondering over deeply philosophical questions, or enjoying the finer things in life, like pedicures and meat straight off the bone.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (90, 277, 'bunny', 'Lapin', 'pets', 1, 148, 1, 2, '1', '1', '0', '0', 'babypets_cata_header', '', '', 'OINK! Partial to a good roll in the mud, these playful piggies have trotted into the hotel and are ready for fun!', '', 'Name your Piglet:', 'Select your colour/breed:\n', 0, '');
INSERT INTO `catalog_pages` VALUES (371, 387, 'welcome_lounge', 'Salon de bienvenue', 'default_3x3', 1, 264, 1, 24, '1', '1', '0', '0', 'catalog_header_classics', 'article_habboreport2', '', 'This furni is from the second version of the Welcome Lounge; the first after moving from Shockwave to Flash.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (89, 277, 'horse', 'Chevaux', 'pets', 1, 132, 1, 7, '1', '1', '0', '0', 'catalog_horse_header2_en', '', '', 'You can ride your horse around the Hotel and customize its body and hair colour.', '', 'Name your Horse:', NULL, 0, '');
INSERT INTO `catalog_pages` VALUES (56, 568, 'cubie', 'Cubie', 'default_3x3', 1, 100, 1, 7, '1', '1', '0', '0', 'catalog_cubie_header_en', 'catalog_cubie_teaser', '', 'It\'s sleek, it\'s modern, it\'s so darn cool it can barely stand itself... Introducing the Cubie Furni range! Give your Bachelor or Bachelorette pad a homely feel with a sophisticated twist.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (370, 387, 'picnic', 'Pique-nique', 'default_3x3', 1, 264, 1, 19, '1', '1', '0', '0', 'catalog_header_classics', 'article_habboreport2', '', 'Picnic is one of the oldest, still-standing Public Rooms on Habbo.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (58, 209, 'american_idol', 'American Idol', 'default_3x3', 1, 52, 1, 1, '1', '1', '0', '0', 'catalog_header_AI1_en', 'catalog_teaser_idol', '', 'Host your own American Idol show with this replica furniture! All that\'s missing is a Randy Jackson lookalike!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (59, 604, 'kitchen', 'Cuisine', 'default_3x3', 1, 217, 1, 5, '1', '1', '0', '0', 'catalog_header_kitchen2015', 'teaser_kitchen2015', '', 'Fancy owning a Habbo restaurant? Or just love catering for Habbos in style? With this furni line you can REALLY get cooking!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (88, 277, 'monkey', 'Singes', 'pets', 1, 166, 1, 9, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'This mischevious monkey has made his way into the hotel and into our hearts. From the tilted beret to his love of bunches of bananas- this Monkey is sure to liven up your Habbo life!', '', 'Name your Monkey:', NULL, 0, '');
INSERT INTO `catalog_pages` VALUES (87, 277, 'dragon', 'Dragons', 'pets', 1, 109, 1, 5, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'Keepers of the Dragon, beware...their history is legendary... With their fiery breath and scaly skin, these mythical creatures are nothing but fierce!', '', 'Name your Dragon:', NULL, 0, '');
INSERT INTO `catalog_pages` VALUES (60, 568, 'usva', 'USVA', 'default_3x3', 1, 129, 1, 23, '1', '0', '0', '0', 'catalog_header_USVA', 'Catalog_teaser_USVA', '', 'With a great range of colours and new stacking possibilities, you\'ll love building and creating structures with the new USVA Furni line!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (279, 209, 'jet_set', 'Jet set', 'default_3x3', 1, 237, 1, 10, '1', '1', '0', '0', 'jetset_header', 'jetset_cashcomp2', '', 'Are you ready for the launch of the new Jet Set series? We are! Get ready to ride the waves on your yacht or jet ski and just relax in a tropical paradise.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (62, 209, 'mystics', 'Mystiques', 'default_3x3', 1, 185, 1, 13, '1', '1', '0', '0', 'header_mystics', 'teaser_mystics', '', 'A mystic crystal has crashed outside the hotel bounds and is transforming the hotel into an infected wilderness. Will you fight for the side for good? Or will you fight for the side of evil and help the infection spread?', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (99963, 99218, 'triggers', 'Déclencheurs', 'default_3x3', 1, 81, 7, 3, '1', '1', '0', '0', 'catalog_wired_header2_en', 'ctlg_pic_wired_triggers', '', 'Triggers let you define what needs to happen for an Effect to take place. To program a Trigger, place it in a room, double click on it and set it up! You need to stack an Effect with the Trigger to make it work.', NULL, NULL, 'Click to see how each Trigger works.', 0, '');
INSERT INTO `catalog_pages` VALUES (604, 5, '', 'Construction de maisons', 'pets3', 1, 88196, 1, 11, '1', '0', '0', '0', '', '', '', '', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (1, 7, '', 'Édition limitée', 'default_3x3', 1, 145, 7, 2, '1', '1', '0', '0', 'limited_header', 'catalog_limited_teaser_en', '', 'Targeted offers Packs', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (602, 5, '', 'Construction de la ville', 'pets3', 1, 72863, 1, 13, '1', '0', '0', '0', '', '', '', '', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (99964, 99218, 'effects', 'Effets', 'default_3x3', 1, 82, 7, 4, '1', '1', '0', '0', 'catalog_wired_header3_en', 'ctlg_pic_wired_effects', '', 'Effects are what happens after you activate a Trigger. To program an Effect, place it in a room, double click on it and set it up! You will always need to stack a Trigger with the Effect to make it work.', NULL, '', 'Click on an item to see what the Effect does!', 0, '');
INSERT INTO `catalog_pages` VALUES (99965, 99218, 'conditions', 'Conditions', 'default_3x3', 1, 83, 7, 5, '1', '1', '0', '0', 'catalog_wired_header4_en', 'ctlg_pic_wired_conditions', '', 'Conditions are specific things that need to be done before a Trigger will work. If you want to use a Condition, you will need to stack it with a Trigger and Effect.', NULL, '', 'Click on an item to see what the Condition does!', 0, '');
INSERT INTO `catalog_pages` VALUES (369, 387, 'lido', 'Piscine', 'default_3x3', 1, 264, 1, 17, '1', '1', '0', '0', 'catalog_header_classics', 'article_habboreport2', '', 'The Lido is where the famous \"Pool\'s Closed\" raid occured in 2006.', '', '', '', 0, '');
