INSERT INTO `catalog_pages` VALUES (70, 209, 'steampunk', 'Steampunk', 'default_3x3', 1, 180, 1, 20, '1', '1', '0', '0', 'catalog_header_steampunk', 'catalog_teaser_steampunk', '', 'Infuse your room design with the power of steam! This Steampunk line is a full set of building material to create amazing room designs that resemble an alternate retro-futuristic universe.', '', '', '', 0, '');
