INSERT INTO `catalog_pages` VALUES (72, 209, 'pirates', 'Pirates', 'default_3x3', 1, 190, 1, 17, '1', '1', '0', '0', 'catalog_header_pirate', 'pirate_bundle', '', 'Yarrr! Harrrrr! Fiddle dee dee, being a pirate is alright with me!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (367, 387, 'hotel_view', 'Vue de l\'hôtel', 'default_3x3', 1, 264, 1, 13, '0', '0', '0', '0', 'catalog_header_classics', 'HotelView', '', 'You can now make the Hotel in your own shape with this furni line.', '', '', '', 0, '');
