INSERT INTO `catalog_pages` VALUES (74, 209, 'habbo_stars', 'Habbo Stars', 'default_3x3', 1, 196, 1, 8, '1', '1', '0', '0', 'habbostars1', 'habbostars2', '', 'Have you always wanted to be famous? Is singing, dancing, or acting your thing? Well we have the next best thing, Wulles Stars! Get your dancing feet on and make your name shine!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (575, 43, 'aquamarine_diner', 'Dîner Aquamarine', 'default_3x3', 1, 204, 1, 8, '1', '1', '0', '0', 'diner', 'catalog_diner_teaser_en', '', 'Originally from the 50\'s this furni has been refurbished and put right into the catalogue! Use this with the Kitchen range for ultimate diner experience!', NULL, NULL, NULL, 0, '');
INSERT INTO `catalog_pages` VALUES (359, 387, 'classic_lounge', 'Salon Classique', 'default_3x3', 1, 264, 1, 2, '1', '1', '0', '0', 'catalog_header_classics', 'classiclounge', '', 'The Welcome Lounge is home not only to newer players, but old Habbo originals who come to guide the newer players or just chill with their friends.', '', '', '', 0, '');
