INSERT INTO `catalog_pages` VALUES (116, 209, 'attic', 'Grenier', 'default_3x3', 1, 242, 1, 1, '1', '1', '0', '0', 'attic15_catalog_header', 'attic15_catalog_teaser', '', 'From idueaky floor boards to ancient furniture, the Attic 2015 furniture is now here!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (118, 209, 'neo-habbo', 'Néo-Habbo', 'default_3x3', 1, 254, 1, 14, '1', '1', '0', '0', 'catalog_header_cpunk15', 'old_cypunk', '', 'Light-filled cityscapes and brightly lit skycrapers looming ovehead... This is the dark, dark furni line of the future. The future is called CyberPunk.', '', '', '', 0, '');
