INSERT INTO `catalog_pages` VALUES (158, 209, 'army_bootcamp', 'Camp d\'entraînement de l\'armée', 'default_3x3', 1, 259, 1, 1, '1', '1', '0', '0', 'catalog_header_army15', 'army_newfurni', '', 'Purchase the new in stock army/military based furni - from gun racks to choppers, no matter what item you\'re after; this section will have it!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (159, 387, 'infobus', 'Infobus', 'default_3x3', 1, 264, 1, 15, '1', '1', '0', '0', 'catalog_header_classics', 'catal_fp_pic5', '', 'The famous Infobus was only ever opened when staff were hosting events or discussions, whereas the park was always open.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (160, 387, 'game_hub', 'Centre de jeux', 'default_3x3', 1, 264, 1, 7, '1', '1', '0', '0', 'catalog_header_classics', 'catal_fp_pic5', '', 'This room was the main collaboration shown of games and events between users and official Habbo staff.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (161, 209, 'paris', 'Paris', 'default_3x3', 1, 261, 1, 17, '1', '1', '0', '0', 'paris_header', 'paris_teaser', '', 'Always wanted to build a Paris designed room? Now is your chance with this brand new set of Paris furniture.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (162, 387, 'hall_of_habbo', 'Salle d\'Habbo', 'default_3x3', 1, 264, 1, 9, '1', '1', '0', '0', 'catalog_header_classics', 'catal_fp_pic5', '', 'It is the least used Public Room, and features users who have won various competitions.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (378, 374, 'classics', 'Classiques', 'default_3x3', 1, 181, 1, 1, '1', '1', '0', '0', 'catalog_easter_headline1', 'catalog_easter_teaser1', '', 'Little birdies hatching from their eggs, pretty, dainty flowers blooming and cute rabbits bouncing in Spring meadows.. it\'s Easter!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (494, 209, 'heroic_acts_certificate', 'Certificat d\'actes héroïques', 'default_3x3', 1, 210, 1, 8, '0', '0', '0', '0', '', '', '', '', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (163, 107, 'groups_forums', 'Groupes Forums', 'guild_forum', 1, 207, 1, 2, '1', '1', '0', '0', 'catalog_groups_en', '', '', 'Group Forums are here!', '', '<b><font color=\"#0e3f52\" size=\"16\">What are Group Forums?</font></b>\r\n\r\nForums allow you to effortlessly post, comment and discuss topics freely, without even leaving the Hotel!\n\n<i><b><font color=\"#0e3f52\" size=\"16\">Who can start a forum? </font></b></i>\n\nOnly a group owner can start a forum for their group.\n\n<i><b><font color=\"#0e3f52\" size=\"16\">Do I need a Forum Terminal?</font></b></i>\n\nYes - In order to start a Group Forum the group owner must first purchase a forum terminal for the group.\n\n\nFind out more about Group Forums <a href=\"event:habbopages/forums\">here</a>.\n\nPlease note, we will continue to add more functionalities to this feature in the near future.', '', 0, '');
INSERT INTO `catalog_pages` VALUES (663, 7, 'v1_rares', 'Rares classiques', 'default_3x3', 1, 256, 7, 4, '1', '1', '0', '0', '', '', '', '', '', '', '', 0, '');
