INSERT INTO `catalog_pages` VALUES (488, 373, '2018_city_festival', '2018 - Fête de la ville', 'default_3x3', 1, 168, 1, 13, '1', '1', '0', '0', 'catalog_header_xmas2013', 'Winter_City_Festival', '', 'Make a beautiful Twinkly Stage and show off your Matryoshka Dolls!', '', '', '', 0, '');
