INSERT INTO `catalog_pages` VALUES (1762, 3135, '', 'Ours', 'default_3x3', 1, 31826, 7, 2, '1', '1', '0', '0', 'Created by iNGH', '', '', NULL, NULL, NULL, NULL, 0, '');
INSERT INTO `catalog_pages` VALUES (1560, 15, 'information_economy', 'Information', 'pets3', 1, 22222, 1, 0, '1', '1', '0', '0', '', 'catalog_icon', '', 'Welcome to the official catalog of Zabbo.ME, created and maintained by Justin.<br><br> For ease of use, check out the Creators tab.<br>Are we missing a furni line you want? Reach out to justinretros on Discord to request it!', 'Economy & Rares', '<img src=\"data:image/png;base64,\" align=\"right\"></a><b>LTD\'s</b><br>LTD Rares are released weekly. Depending on demand and user activity, we tend to release 1-2 LTD\'s at a time for varying costs of varying currencies.<br><br><b>Featured Rares</b> <br>Every month we will feature two classic rare items available for purchase directly from the catalog. These items are also available, at your risk, using our Cases interface.<br><br>Zabbo prides itself on maintaing a fair and strict economy. These include using tools such as dice rolling logs, trade logs, marketplace logs, pay logs and auto-game logs to monitor new trends and to determine if any abuses occoured within the hotel. Trade data and Marketplace data is accurately analyzed to provide approximate trade values of items, which can be found on the Rare Values popup underneath the level system.', '<img src=\"data:image/gif;base64,\" align=\"left\" style=\"padding-right: 5px;margin-top: -2px;\">Your purchases and trade logs are monitored by Hotel Management.', 0, '');
INSERT INTO `catalog_pages` VALUES (487, 373, '2017_victorian', '2017 - Victorien', 'default_3x3', 1, 168, 1, 12, '1', '1', '0', '0', 'catalog_header_xmas2013', 'spromo_adventxmas17', '', 'More shopping, less markets. Big corporations ruined the Christmas markets; but at least they sell less of the same product for a higher price!', '', '', '', 0, '');
