INSERT INTO `catalog_pages` VALUES (1243445, 1243444, 'triggers_custom', 'Déclencheurs', 'default_3x3', 1, 81, 1, 1, '1', '1', '0', '0', 'catalog_wired_header2_en', 'ctlg_pic_wired_triggers', '', 'Triggers let you define what needs to happen for an Effect to take place. To program a Trigger, place it in a room, double click on it and set it up! You need to stack an Effect with the Trigger to make it work.', NULL, NULL, 'Click to see how each Trigger works.', 0, '');
