INSERT INTO `catalog_pages` VALUES (83, 277, 'spider', 'Araignées', 'pets', 1, 95, 1, 13, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'One of the most feared creatures in nature, and perhaps the most misunderstood. The majority of Spiders have sharp fangs that inject venom into their prey- but don\'t worry, these spiders won\'t bite! Maybe...', '', 'Name your pet:', '', 0, '');
INSERT INTO `catalog_pages` VALUES (82, 277, 'rhino', 'Rhinocéros', 'pets', 1, 77, 1, 12, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'The Rhinoceros is an African herbivore that can weigh over a ton. It is proud and slightly aloof, but loyal and never let anything get in the way of a good time!', 'Name your pet:', 'Choose a colour:', 'Choose a breed:', 0, '');
INSERT INTO `catalog_pages` VALUES (81, 277, 'lion', 'Lions', 'pets', 1, 76, 1, 8, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'A boisterous predator in nature, the lion has been tamed to be your fierce friend in Habbo Hotel.', 'Name your pet:', 'Choose a colour:', 'Choose a breed:\n', 0, '');
INSERT INTO `catalog_pages` VALUES (46, 253, 'trax', 'Musique', 'default_3x3', 1, 4, 1, 2, '1', '1', '0', '0', 'music_header', 'hotelhits_teaser', '', 'Trax are the Habbo music disks which have many multiple tunes installed onto them which can be played on a Trax Machine in the room. After the Habbo transistion from Shockwave to Flash clients, the trax system was not recovered until April 2011, where only Juke Boxes, old CDs, and Habbo sold CDs were re-released.', '', 'For decoration only.. They do not function.', '', 0, '');
