INSERT INTO `catalog_pages` VALUES (79, 277, 'bears', 'Ours', 'pets', 1, 68, 1, 1, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'A large mammal that walks on the soles of its feet, with thick fur and a short tail. Did you know that bears are related to dogs and that most species are omnivorous?', 'Name your Bear:', NULL, 'Pick a breed:', 0, '');
INSERT INTO `catalog_pages` VALUES (2234737, 222, '', 'Escaliers', 'default_3x3', 1, 754120, 1, 5, '1', '1', '0', '0', '', '', '', NULL, NULL, NULL, NULL, 0, '');
