INSERT INTO `catalog_pages` VALUES (78, 277, 'terriers', 'Terriers', 'pets', 1, 66, 1, 14, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'The Cairn Terrier is one of the oldest terrier breeds. From the Scottish Highlands, it was used for hunting prey among the cairns! Different breeds have different colours!', 'Name your Terrier:', 'Pick a colour:', 'Pick a breed:\n', 0, '');
INSERT INTO `catalog_pages` VALUES (77, 277, 'crocs', 'Crocs', 'pets', 1, 22, 1, 3, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'Scaly skin, growls and snaps! Security for your room or used to scare your friends - this surprisingly loving Croc can be yours.', 'Name your Croc:', 'Pick a colour:', 'Pick a breed:', 0, '');
INSERT INTO `catalog_pages` VALUES (76, 277, 'cats', 'Chats', 'pets', 1, 20, 1, 2, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'Fluff, whiskers, meows and purrs! These cute little critters make great playmates and will keep you entertained.', 'Name your Cat:', 'Pick a colour:', 'Pick a breed:', 0, '');
INSERT INTO `catalog_pages` VALUES (75, 277, 'dogs', 'Chiens', 'pets', 1, 24, 1, 4, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'Wet noses, paws and woofs! You\'re about to enter the world of Habbo Dogs. An adorable and cuddly ball of fur awaits you with a waggling tail.', 'Name your Dog:', 'Pick a colour:', 'Pick a breed:', 0, '');
INSERT INTO `catalog_pages` VALUES (2512, 25, 'badge_display', 'Affichage des badges', 'badge_display', 1, 35800, 1, 1, '1', '1', '0', '0', 'catalog_header_badgedisplay', 'badges', '', 'Express yourself with Badges!<br>Put those useless Duckets to use and show off your personality with our wide range of badges.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (123721, 12371, 'diamonds', 'Diamants cachés', 'default_3x3', 1, 92, 7, 2, '1', '1', '0', '0', '', 'catalog_diamond21_teaser', '', 'You can exchange your Zabbo diamonds here for Exchange furniture, which you can use in a trade or simply exchange for actual diamonds. Please note, the redeem window will say you\'re redeeming for credits, ignore this - you will be given diamonds.', ' ', ' ', NULL, 0, '');
INSERT INTO `catalog_pages` VALUES (9965235, 100, '', 'Nouvelle page', 'default_3x3', 1, 1, 1, 1, '1', '1', '0', '0', '', '', '', ' ', ' ', ' ', ' ', 0, '');
INSERT INTO `catalog_pages` VALUES (879, 2, 'information_classic', 'Information', 'pets3', 1, 22222, 1, 1, '1', '1', '0', '0', '', 'catalog_icon', '', 'Welcome to the official catalog of Zabbo.ME, created and maintained by Justin.<br><br> For ease of use, check out the Creators tab.<br>Are we missing a furni line you want? Reach out to justinretros on Discord to request it!', 'Welcome to Zabbo Catalog v1', '<img src=\"data:image/png;base64,\" align=\"right\"></a>Enjoy building? Well, we\'ve got just the catalog for you! For ease of use, check out the Creators tab, where you will find neatly organized categories to help spend you less time searching the catalog and more time building beautiful rooms!<br><br><b>Are we missing a furni line you want to see on Zabbo?</b><br> Post a suggestion in our <a href=\"https://discord.gg/zabbo\" target=\"_blank\"><b>Discord</b></a> with the furniture line\'s name, and a screenshot of the items and we will add it ASAP!', '<img src=\"data:image/gif;base64,\" align=\"left\" style=\"padding-right: 5px;margin-top: -2px;\">This catalog is maintained by <b>Justin</b>.', 0, '');
