INSERT INTO `catalog_pages` VALUES (12371, 12, 'diamonds', 'Diamants', 'default_3x3', 1, 92, 1, 2, '1', '1', '0', '0', '', 'catalog_diamond21_teaser', '', 'You can exchange your Zabbo diamonds here for Exchange furniture, which you can use in a trade or simply exchange for actual diamonds. Please note, the redeem window will say you\'re redeeming for credits, ignore this - you will be given diamonds.', ' ', ' ', NULL, 0, '');
