INSERT INTO `catalog_pages` VALUES (63, 218, 'triggers', 'Déclencheurs', 'default_3x3', 1, 81, 1, 2, '1', '1', '0', '0', 'catalog_wired_header2_en', 'ctlg_pic_wired_triggers', '', 'Triggers let you define what needs to happen for an Effect to take place. To program a Trigger, place it in a room, double click on it and set it up! You need to stack an Effect with the Trigger to make it work.', NULL, NULL, 'Click to see how each Trigger works.', 0, '');
INSERT INTO `catalog_pages` VALUES (64, 218, 'effects', 'Effets', 'default_3x3', 1, 82, 1, 3, '1', '1', '0', '0', 'catalog_wired_header3_en', 'ctlg_pic_wired_effects', '', 'Effects are what happens after you activate a Trigger. To program an Effect, place it in a room, double click on it and set it up! You will always need to stack a Trigger with the Effect to make it work.', NULL, '', 'Click on an item to see what the Effect does!', 0, '');
INSERT INTO `catalog_pages` VALUES (65, 218, 'conditions', 'Conditions', 'default_3x3', 1, 83, 1, 4, '1', '1', '0', '0', 'catalog_wired_header4_en', 'ctlg_pic_wired_conditions', '', 'Conditions are specific things that need to be done before a Trigger will work. If you want to use a Condition, you will need to stack it with a Trigger and Effect.', NULL, '', 'Click on an item to see what the Condition does!', 0, '');
