INSERT INTO `catalog_pages` VALUES (6791, 7, 'what_you_can_do', 'Ce que vous pouvez faire', 'info_loyalty', 1, 42, 7, 70111, '1', '1', '0', '0', '', '', '', 'Page Text 1: <font color=\"#eb3528\">You</font> <font color=\"#e69d20\">can</font> <font color=\"#e3dc19\">use</font> <font color=\"#8ae324\">any</font> <font color=\"#63e622\">colour</font> <font color=\"#19e3ad\">you</font> <font color=\"#1856db\">would</font> <font color=\"#6d18db\">like.</font>\r\n<font size=\"15\">And any size.</font><br>\r\n<font color=\"#9c0500\">I use red a lot on my staff pages, and of course <b>bold for emphasis,</b> <i>italics are important</i>, and <u>underlining.</u></font><br>\r\nYou can add events to <b>some</b> page types too.<br>\r\n<a href=\"event:habbopages/chat\">This opens a habbopage.</a><br>\r\n<a href=\"event:toolbar/memenu\">This opens your menu.</a><br>\r\n<a href=\"event:navigator/search/ridge.fun\">This searches the navigator.</a><br>\r\n<a href=\"event:avatareditor/open\">This opens the Avatar Editor.</a><br>\r\n<font size=\"15\"><i>You get the idea.</i><br>\r\n<font size=\"13\">Enjoy the catalogue!</font>', NULL, NULL, NULL, 0, '');
